        { name: "Enterprise", priceLabel: "Custom", description: "Security, scale, and dedicated help.", features: ["Everything in Pro", "SSO & SCIM", "Dedicated infra", "SLA & onboarding"], cta: { label: "Contact sales", href: "#" } },
